import parse
import re

p = parse.Parser('''
letters: {:w}
non-letters: {:W}
whitespace: \"{0}\"
non-whitespace: \t{1}\n
digits: {2:d} {3:d}
non-digits: {4:D}
numbers with thousands: {5:n}
fixed-point: {6:f}
floating-point: {7:e}
general numbers: {8:g} {9:g}
binary: {10:b}
octal: {11:o}
hex: {12:x}
ISO 8601 e.g. {13:ti}
RFC2822 e.g. {14:te}
Global e.g. {15:tg}
US e.g. {16:ta}
ctime() e.g. {17:tc}
HTTP e.g. {18:th}
time: {19:tt}
final value: {20}
''')

print('Fixed fields:', p._fixed_fields)
print('Type conversions:', list(p._type_conversions.keys()))

data = '''
letters: abcdef_GHIJLK
non-letters: !@#\$ *^%
whitespace: \"   \\t\\n\"
non-whitespace: \\tabc\\n
digits: 12345 0b1011011
non-digits: abcdef
numbers with thousands: 1,000
fixed-point: 100.2345
floating-point: 1.1e-10
general numbers: 1 1.1
binary: 0b1000
octal: 0o1000
hex: 0x1000
ISO 8601 e.g. 1972-01-20T10:21:36Z
RFC2822 e.g. Mon, 20 Jan 1972 10:21:36 +1000
Global e.g. 20/1/1972 10:21:36 AM +1:00
US e.g. 1/20/1972 10:21:36 PM +10:30
ctime() e.g. Sun Sep 16 01:03:52 1973
HTTP e.g. 21/Nov/2011:00:07:11 +0000
time: 10:21:36 PM -5:30
final value: spam
'''

m = re.match(p._expression, data)
if m:
    print('\\nGroups:')
    for i, g in enumerate(m.groups()):
        if i < len(p._fixed_fields):
            print(f'  [{i}] = {g!r}')
        else:
            print(f'  [{i}] = {g!r} (extra)')
"
